import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 조회 구분 값은 화면 문구 그대로 사용한다.
const BOX_MINE = '작성 문서';
const BOX_SHARED = '공유 문서';
const BOX_RECEIVED = '공유받은 문서';
const BOX_TYPES = [BOX_MINE, BOX_SHARED, BOX_RECEIVED];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

@Controller('api/v1')
export class FnSfr04104Controller {
  @Post('/office-documents/:officeDocumentId/sync-ecm')
  @HttpCode(200)
  async syncOfficeDocumentToEcm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const id = req.params['officeDocumentId'];
    if (!/^\d+$/.test(id)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT office_document_id AS "officeDocumentId",
                author_id AS "authorId",
                ecm_sync_status AS "ecmSyncStatus"
           FROM office_document
          WHERE office_document_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'OFFICE_DOCUMENT_NOT_FOUND', '연계할 문서를 찾을 수 없습니다.');
      }
      const doc = rows[0];
      // 가정: 본인이 작성한 문서만 연계할 수 있다.
      if (String(doc['authorId']) !== user.id) {
        throw new ApiError(403, 'FORBIDDEN', '권한이 없습니다.');
      }
      // 이미 ECM에 연계 완료된 문서는 중복 저장하지 않는다.
      if (doc['ecmSyncStatus'] === '완료') {
        throw new ApiError(409, 'ECM_DUPLICATE_DOCUMENT', 'ECM에 동일한 문서가 이미 있습니다.');
      }
      // 가정: ECM 식별자는 문서 ID로 만든다 (실제 ECM 호출 방식이 입력에 없음).
      const updated = await db.query(
        `UPDATE office_document
            SET ecm_document_id = 'ECM-' || CAST(office_document_id AS text),
                ecm_sync_status = '완료',
                ecm_synced_at = now(),
                ecm_fail_reason = NULL,
                updated_at = now()
          WHERE office_document_id = CAST(:id AS bigint)
          RETURNING office_document_id AS "officeDocumentId",
                    ecm_document_id AS "ecmDocumentId",
                    ecm_sync_status AS "ecmSyncStatus",
                    ecm_fail_reason AS "ecmFailReason"`,
        { id },
      );
      return updated[0];
    });
  }

  @Get('/ecm-documents')
  async listEcmDocuments(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const boxType = query['boxType'];
    if (boxType === undefined || boxType === null || String(boxType) === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '조회 구분을 선택하세요.');
    }
    if (!BOX_TYPES.includes(String(boxType))) {
      throw new ApiError(422, 'INVALID_DOCUMENT_BOX_TYPE', '조회 구분이 올바르지 않습니다.');
    }
    const pageText = query['page'] === undefined || query['page'] === '' ? '0' : String(query['page']);
    const sizeText = query['size'] === undefined || query['size'] === '' ? String(DEFAULT_SIZE) : String(query['size']);
    if (!/^\d+$/.test(pageText) || !/^\d+$/.test(sizeText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
    }
    const page = Number(pageText);
    const size = Math.min(Math.max(Number(sizeText), 1), MAX_SIZE);
    const title = query['title'] ? String(query['title']) : '';
    const createdFrom = query['createdFrom'] ? String(query['createdFrom']) : '';
    const createdTo = query['createdTo'] ? String(query['createdTo']) : '';
    if ((createdFrom && !DATE_PATTERN.test(createdFrom)) || (createdTo && !DATE_PATTERN.test(createdTo))) {
      throw new ApiError(400, 'VALIDATION_FAILED', '작성일 형식이 올바르지 않습니다.');
    }
    // 가정: 공유 문서·공유받은 문서를 담은 테이블이 입력에 없어 빈 목록을 돌려준다.
    if (boxType !== BOX_MINE) {
      return { items: [], page, size, total: 0 };
    }
    return transaction(async (db) => {
      const params = {
        userId: user.id,
        title,
        createdFrom,
        createdTo,
        limit: size,
        offset: page * size,
      };
      const where = `WHERE author_id = CAST(:userId AS bigint)
           AND (:title = '' OR title ILIKE '%' || :title || '%')
           AND (:createdFrom = '' OR created_at >= CAST(:createdFrom AS date))
           AND (:createdTo = '' OR created_at < CAST(:createdTo AS date) + 1)`;
      const countRows = await db.query(
        `SELECT COUNT(*) AS "total" FROM office_document ${where}`,
        params,
      );
      const items = await db.query(
        `SELECT office_document_id AS "officeDocumentId",
                title AS "title",
                ecm_document_id AS "ecmDocumentId",
                ecm_sync_status AS "ecmSyncStatus"
           FROM office_document
           ${where}
          ORDER BY created_at DESC, office_document_id DESC
          LIMIT :limit OFFSET :offset`,
        params,
      );
      return { items, page, size, total: Number(countRows[0]['total']) };
    });
  }
}

