import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  Drawer,
  Field,
  Filters,
  Form,
  Pager,
  Pairs,
  Select,
  Tiles,
  TextInput,
  DateInput,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const BOX_OPTIONS: [string, string][] = [
  ['작성 문서', '작성 문서'],
  ['공유 문서', '공유 문서'],
  ['공유받은 문서', '공유받은 문서'],
];
const PAGE_SIZE = 20;

export default function FnSfr04104Page({ role, notify }: PageProps) {
  const [boxType, setBoxType] = useState('작성 문서');
  const [title, setTitle] = useState('');
  const [createdFrom, setCreatedFrom] = useState('');
  const [createdTo, setCreatedTo] = useState('');
  const [applied, setApplied] = useState<Row>({ boxType: '작성 문서' });
  const [page, setPage] = useState(0);
  const [detail, setDetail] = useState<Row | null>(null);
  const [syncTarget, setSyncTarget] = useState<Row | null>(null);

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/ecm-documents', role, undefined, { ...applied, page, size: PAGE_SIZE }),
    [applied, page, role],
  );

  const rows = data ? data.items : [];
  const countOf = (status: string) => rows.filter((r) => r.ecmSyncStatus === status).length;

  const search = () => {
    setPage(0);
    setApplied({ boxType, title, createdFrom, createdTo });
  };

  const reset = () => {
    setBoxType('작성 문서');
    setTitle('');
    setCreatedFrom('');
    setCreatedTo('');
    setPage(0);
    setApplied({ boxType: '작성 문서' });
  };

  const sync = async () => {
    if (!syncTarget) return;
    await call('POST', `/office-documents/${String(syncTarget.officeDocumentId)}/sync-ecm`, role, {});
    notify('ECM에 연계 저장했습니다.');
    setSyncTarget(null);
    reload();
  };

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>연계 현황</h2>
        <Tiles
          items={[
            ['전체 문서', data ? data.total : 0],
            ['연계 완료', countOf('완료')],
            ['연계 대기', countOf('대기')],
            ['재처리 대상', countOf('재처리대상')],
          ]}
        />
      </section>
      <section className="box span-12">
        <h2>ECM 문서</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 구분" required>
            <Select value={boxType} onChange={setBoxType} options={BOX_OPTIONS} />
          </Field>
          <Field label="문서 제목">
            <TextInput value={title} onChange={setTitle} />
          </Field>
          <Field label="작성일 시작">
            <DateInput value={createdFrom} onChange={setCreatedFrom} />
          </Field>
          <Field label="작성일 종료">
            <DateInput value={createdTo} onChange={setCreatedTo} />
          </Field>
        </Filters>
        <Band total={data ? data.total : 0} />
        {error ? <p>{error}</p> : null}
        {loading ? <p>불러오는 중입니다.</p> : null}
        <DataTable
          rows={rows}
          empty="조회된 문서가 없습니다."
          onRowClick={(row) => setDetail(row)}
          columns={[
            { key: 'officeDocumentId', label: '웹오피스 문서 ID' },
            { key: 'title', label: '문서 제목' },
            { key: 'ecmDocumentId', label: 'ECM 문서 식별자' },
            {
              key: 'ecmSyncStatus',
              label: 'ECM 연계 상태',
              render: (row) => <Badge value={row.ecmSyncStatus} />,
            },
            {
              key: 'action',
              label: '처리',
              render: (row) =>
                row.ecmSyncStatus === '대기' || row.ecmSyncStatus === '재처리대상' ? (
                  <button
                    type="button"
                    onClick={(e) => {
                      e.stopPropagation();
                      setSyncTarget(row);
                    }}
                  >
                    ECM 연계
                  </button>
                ) : null,
            },
          ]}
        />
        <Pager page={page} size={PAGE_SIZE} total={data ? data.total : 0} onPage={setPage} />
      </section>
      {detail ? (
        <Drawer title="문서 상세" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['웹오피스 문서 ID', String(detail.officeDocumentId)],
              ['문서 제목', String(detail.title ?? '')],
              ['ECM 문서 식별자', String(detail.ecmDocumentId ?? '')],
              ['ECM 연계 상태', <Badge value={detail.ecmSyncStatus} />],
            ]}
          />
        </Drawer>
      ) : null}
      {syncTarget ? (
        <Drawer title="ECM 연계 저장" onClose={() => setSyncTarget(null)}>
          <Form
            onSubmit={sync}
            submit="ECM에 연계"
            note={`'${String(syncTarget.title ?? '')}' 문서를 ECM에 연계 저장합니다.`}
          >
            <Pairs
              items={[
                ['웹오피스 문서 ID', String(syncTarget.officeDocumentId)],
                ['ECM 연계 상태', <Badge value={syncTarget.ecmSyncStatus} />],
              ]}
            />
          </Form>
        </Drawer>
      ) : null}
    </div>
  );
}
